using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CasinoOpenRoadsideVerify{static CasinoOpenRoadsideVerify(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CasinoOpenRoadsideVerify.request"))return;var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var root=scene.GetRootGameObjects().FirstOrDefault(g=>g.name=="Casino Open Roadside Logo 32");if(!root)return;File.Delete("CasinoOpenRoadsideVerify.request");try{var center=root.transform.position;var capture=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);capture.Invoke(null,new object[]{scene,center+new Vector3(11,3,20),center+Vector3.down*1.6f,"Casino-Billboard-32-Open-Front"});capture.Invoke(null,new object[]{scene,center+new Vector3(-11,3,-20),center+Vector3.down*1.6f,"Casino-Billboard-32-Open-Back"});var ctrl=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();bool night=ctrl.IsNight;try{ctrl.ApplyNight();capture.Invoke(null,new object[]{scene,center+new Vector3(11,3,20),center+Vector3.down*1.6f,"Casino-Billboard-32-Open-Night"});}finally{if(night)ctrl.ApplyNight();else ctrl.ApplyDay();}File.WriteAllText("FinalEnvironmentRoadReview/CasinoOpenRoadsideVerified.txt","SUCCESS front/back/night renders. LOD meshes="+string.Join(",",root.GetComponentsInChildren<MeshFilter>(true).Select(f=>f.sharedMesh.triangles.Length/3))+" triangles. Existing materials="+root.GetComponentsInChildren<Renderer>(true).SelectMany(r=>r.sharedMaterials).Distinct().Count()+"; runtime lights="+root.GetComponentsInChildren<Light>(true).Length+"; shader errors="+root.GetComponentsInChildren<Renderer>(true).SelectMany(r=>r.sharedMaterials).Any(m=>ShaderUtil.ShaderHasError(m.shader)));}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/CasinoOpenRoadsideVerified.txt",e.ToString());Debug.LogException(e);}}}
